import itertools

def get_connections(edges):
    connections = set()
    for u, v in edges:
        connections.add((u, v))

    changed = True
    while changed:
        changed = False
        for u, v in list(connections):
            for v2, w in list(connections):
                if v == v2:
                    if (u, w) not in connections:
                        connections.add((u, w))
                        changed = True
    return connections

def solve(N):
    # All possible edges (u, v) with 1 <= u < v <= N
    all_edges = []
    for u in range(1, N + 1):
        for v in range(u + 1, N + 1):
            all_edges.append((u, v))

    # All possible sets of k edges satisfying the S_i < S_{i+1} and B_i < B_{i+1} conditions
    def get_valid_edge_sets(k):
        valid_sets = []
        for edges in itertools.combinations(all_edges, k):
            sorted_edges = sorted(edges) # sort by S_i
            # check if B_i are also sorted
            if all(sorted_edges[i][1] < sorted_edges[i+1][1] for i in range(k-1)):
                valid_sets.append(sorted_edges)
        return valid_sets

    for k in range(1, N):
        valid_sets = get_valid_edge_sets(k)
        # For this k, is it true that for all pairs of valid_sets, they share a connection?
        all_share = True
        for set_a, set_b in itertools.product(valid_sets, repeat=2):
            conn_a = get_connections(set_a)
            conn_b = get_connections(set_b)
            if not (conn_a & conn_b):
                all_share = False
                break
        if all_share:
            return k
    return N - 1

for n in range(2, 7):
    print(f"N={n}, k={solve(n)}")

