    for u, v in edges:
        connections.add((u, v))

    changed = True
    while changed:
        changed = False
        # If x -> v and u -> y and v <= u, then x -> y
        for x, v in list(connections):
            for u, y in list(connections):
                if v <= u:
                    if (x, y) not in connections:
                        connections.add((x, y))
                        changed = True
    return connections

