def solve_n_k(N, k):
    # This is too slow, let's just try to find a counterexample
    # using a random search.
    import random
    for _ in range(100000):
        # Generate two valid sets of k edges
        def gen_valid_set():
            S = sorted(random.sample(range(1, N + 1), k))
            B = sorted(random.sample(range(1, N + 1), k))
            # We need S_i < B_i for all i
            # This is not guaranteed. Let's just generate S and B and check.
            if all(S[i] < B[i] for i in range(k)):
                return list(zip(S, B))
            return None

        set_a = gen_valid_set()
        set_b = gen_valid_set()
        if set_a and set_b:
            conn_a = get_connections(set_a)
            conn_b = get_connections(set_b)
            if not (conn_a & conn_b):
                return False # Found a counterexample
    return True # No counterexample found

